&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les arch&#233;types de pistolier&lt;a class=&quot;headeranchor&quot; id=&quot;Les_arch&#233;types_de_pistolier_0&quot; href=&quot;#Les_arch&#233;types_de_pistolier_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Pistolier.html&quot; title=&quot;Le pistolier&quot;&gt;classe&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Arbal&#233;trier-D&#233;lite-(Pistolier).html&quot; title=&quot;Arbal&#233;trier d&amp;#39;&#233;lite&quot;&gt;Arbal&#233;trier d&#39;&#233;lite&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Armure-Pistolet-(Pistolier).html&quot; title=&quot;Armure-pistolet&quot;&gt;Armure-pistolet&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Boucanier-(Pistolier).html&quot; title=&quot;Boucanier&quot;&gt;Boucanier&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;Humain&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fabricant-De-Pistolets-Exp&#233;rimentaux-(Pistolier).html&quot; title=&quot;Fabricant de pistolets exp&#233;rimentaux&quot;&gt;Fabricant de pistolets exp&#233;rimentaux&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gnome.html&quot; title=&quot;Les gnomes&quot;&gt;Gnome&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gu&#233;rillero-(Pistolier).html&quot; title=&quot;Gu&#233;rillero&quot;&gt;Gu&#233;rillero&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Kobold-(Race).html&quot; title=&quot;Les kobolds&quot;&gt;Kobold&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Du-Mousquet-(Pistolier).html&quot; title=&quot;Ma&#238;tre du mousquet&quot;&gt;Ma&#238;tre du mousquet&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Myst&#233;rieux-Voyageur-(Pistolier).html&quot; title=&quot;Myst&#233;rieux voyageur&quot;&gt;Myst&#233;rieux voyageur&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pistolero-(Pistolier).html&quot; title=&quot;Pistolero&quot;&gt;Pistolero&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rebelle-(Pistolier).html&quot; title=&quot;Rebelle&quot;&gt;Rebelle&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tireur-Des-Ravins-(Pistolier).html&quot; title=&quot;Tireur des ravins&quot;&gt;Tireur des ravins&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Homme-Rat-(Race).html&quot; title=&quot;Les hommes-rats&quot;&gt;Homme-rat&lt;/a&gt;) (MR)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;script&gt;
